async function logout(){
  try{
    const refresh=localStorage.getItem('bp_refresh');
    if(refresh) await BP.api('/api/v1/auth/logout/',{method:'POST',body:JSON.stringify({refresh})});
  }catch(e){}
  BP.clearSession();
  notes=[];
  pendingRegister=null;
  profile={name:'Mehmon',business:'—',region:'—',phone:'',activity:'',market:'',vehicle:'',capacity:''};
  navigate('login');
  notify('Tizimdan chiqdingiz');
}
async function loadNotes(){
  if(!BP.isAuthed()){notes=[];return}
  notes=await BP.api('/api/v1/notebook/entries/');
}
async function bootSession(){
  try{
    if(BP.isAuthed()){
      const me=await BP.api('/api/v1/me/');
      BP.setSession({user:me,access:BP.getAccess(),refresh:localStorage.getItem('bp_refresh')});
      applyUser(me);
      await loadNotes();
    }
  }catch(e){
    BP.clearSession();
    bootError=e.message||'Sessiya ochilmadi';
  }finally{
    sessionReady=true;
    guardAndRender();
  }
}
function guardAndRender(){
  if(!sessionReady){
    $('#app').innerHTML=`<div class="card auth" style="margin:40px auto;max-width:480px"><p>Kabinet yuklanmoqda…</p></div>`;
    return;
  }
  const p=location.hash.slice(1)||'overview';
  page=titles[p]?p:'overview';
  if(!BP.isAuthed() && !PUBLIC_PAGES.has(page)){
    page='login';
    if(location.hash!=='#login') history.replaceState(null,'','#login');
  }
  if(BP.isAuthed() && (page==='login'||page==='register'||page==='role')){
    page='overview';
    if(location.hash!=='#overview') history.replaceState(null,'','#overview');
  }
  render();
}
