const courses=[['Biznesni noldan boshlash','G‘oyani tekshirish, mijozni topish va birinchi savdo.','Biznes asoslari',6,42,'bag',''],['Pul oqimi va haqiqiy foyda','Tushum, xarajat va foydani to‘g‘ri ajrating.','Moliya',5,35,'chart','blue'],['Bitta safar qancha turadi?','Yoqilg‘i, qaytish yo‘li va yashirin xarajatlar.','Logistika',4,28,'truck','yellow'],['Mahsulot narxini belgilash','Marja, ustama va zararsizlik nuqtasi.','Moliya',4,32,'calc',''],['Soliq va hujjatlar asoslari','Manbalarni tekshirish va hujjatlarni tartiblash.','Huquq',5,40,'file','yellow'],['Mijoz bilan samarali savdo','Qiymat taklifi, muzokara va kelishuv.','Biznes asoslari',4,30,'user','blue']];
function learning(){return header('Bilim — biznesingizning eng yaxshi kapitali.','Qisqa darslar. Amaliy misollar. O‘z sur’atingizda o‘rganing.',link('Profil yaratish','register'))+`<section class="hero-learn"><div><span class="badge">BOSHLASH UCHUN</span><h2>Bugungi bilimingiz —<br>ertangi o‘sishingiz.</h2><p>Tadbirkorlik, moliya va logistika bo‘yicha amaliy yo‘l.</p>${btn('Birinchi darsni ochish →','onclick="openCourse(0)"')}</div><div class="learn-block">O‘QUV YO‘NALISHLARI<strong>04</strong>Bilimdan amaliyotga</div></section><div class="pillrow">${['Barchasi','Biznes asoslari','Moliya','Logistika','Huquq'].map(c=>`<button class="chip ${category===c?'active':''}" onclick="category='${c}';render()">${c}</button>`).join('')}</div><div class="grid courses">${courses.map((c,i)=>category!=='Barchasi'&&c[2]!==category?'':`<article class="card course"><div class="course-top ${c[6]}"><span>${c[2].toUpperCase()}</span>${icon(c[5])}</div><h3>${c[0]}</h3><p>${c[1]}</p><div class="subtext">${c[3]} dars · ${c[4]} daqiqa · Boshlang‘ich</div><div class="progress"><i style="width:${completedCourses.has(i)?100:0}%"></i></div>${btn(completedCourses.has(i)?'Takrorlash →':'Namuna darsni ochish →',`onclick="openCourse(${i})"`,true)}</article>`).join('')}</div>`}
function openCourse(i){let texts=['G‘oyani tekshirish uchun avval kimning qanday muammosini hal qilishingizni yozing. Kamida 5 potensial mijoz bilan suhbatlashing. Mahsulot tayyorlashdan oldin ularning mavjud yechimi, xarajati va sizdan kutayotgan natijasini bilib oling.','Tushum — sotuvdan olingan qiymat. Pul oqimi — kirgan va chiqqan pul farqi. Foyda — tushumdan tegishli tannarx va xarajatlar ayirmasi. Masalan, olingan kredit pul qoldig‘ini ko‘paytiradi, lekin foyda emas.','Safar narxida faqat dizel hisobini olish yetarli emas. Bo‘sh qaytish yo‘li, yuklash, haydovchi, yo‘l to‘lovlari va avtomobil eskirishini ham kiriting. Keyin narx bilan jami xarajatni taqqoslang.','10 000 so‘mlik mahsulot tannarxi 6 000 so‘m bo‘lsa, birlik hissasi 4 000 so‘m. Doimiy xarajat 200 000 so‘m bo‘lsa, 50 dona sotishda zararsizlikka chiqasiz. Marja va ustama turli maxrajlar bilan hisoblanadi.','Majburiyatlarni aniqlash uchun biznes shakli, faoliyat turi, davr va rasmiy manbalarni tekshiring. Stavka yoki talabni sanasiz qo‘llamang. Mazkur namuna dars aniq yuridik maslahat bermaydi.','Mijozning maqsadini aniqlang, mahsulotingiz qanday natija berishini tushuntiring va narxdan tashqari shartlarni ham yozing: hajm, sifat, yetkazish va qabul qilish.'];modal(courses[i][0],`<span class="badge">Namuna mikro-dars</span><p style="line-height:1.9">${texts[i]}</p><div class="notice">Amaliy topshiriq: ushbu bilimni o‘z biznesingizga mos bitta misolda yozib chiqing.</div>${btn('O‘qib bo‘ldim '+icon('check'),`onclick="completedCourses.add(${i});document.querySelector('#modal').close();render();notify('Dars demo sessiyasida tugallandi')"`)}`)}
function planPage(){let t=tab||'Reja';return header('G‘oyangizga raqamlar bilan qarang.','Rejalashtiring, hisoblang va xavflarni oldindan ko‘ring.')+tabs(['Reja','Kalkulyator','Stress-test','Soliq','Kredit markazi','Keyslar'])+(t==='Soliq'?`<div class="card"><h2>Soliq markazi</h2><p class="muted">Faoliyat va yuridik shaklingizga mos manbalarni tekshirish.</p><div class="notice">Rasmiy manbalar integratsiyasi hali ulanmagan. Bu yerda stavkalar yoki huquqiy xulosa berilmaydi.</div><div class="formgrid">${selectField('Biznes shakli','legal',['Yakka tartibdagi tadbirkor','MChJ','O‘zini o‘zi band qilgan'])}${field('Faoliyat turi','activity','Chakana savdo','text')}</div>${btn('Tekshirish ro‘yxatini ko‘rish','onclick="taxChecklist()"')}</div>`:t==='Kredit markazi'?creditPage():t==='Keyslar'?`<div class="grid two-col"><div class="card"><span class="badge">Hisoblash misoli</span><h2>Kichik savdo nuqtasi</h2><p>100 dona × 10 000 so‘m. Tannarx 6 000 so‘m/dona, doimiy xarajat 200 000 so‘m.</p><div class="result"><strong>200 000 so‘m</strong><p>Soliq va foizdan oldingi operatsion foyda. Zararsizlik: 50 dona.</p></div></div><div class="card"><span class="badge">Logistika misoli</span><h2>Qaytish yo‘lini unutmang</h2><p>200 km yo‘l, 12 l/100 km, 10 000 so‘m/l. Boshqa xarajat: 100 000 so‘m.</p><div class="result"><strong>340 000 so‘m</strong><p>Faqat kiritilgan 200 km uchun jami xarajat; bo‘sh qaytish alohida hisoblanadi.</p></div></div></div>`:`<div class="grid two-col"><form class="card" id="businessForm" oninput="calcBusiness()" onsubmit="event.preventDefault();generatePlan()"><div class="cardhead"><h2>${t==='Reja'?'Biznesingiz parametrlari':t==='Stress-test'?'Ssenariyni tekshiring':'Birlik iqtisodiyoti'}</h2><span class="badge">UZS</span></div>${t==='Reja'?field('Biznes g‘oyasi','idea','Mahalliy mahsulotlar ulgurji savdosi','text'):''}<div class="formgrid">${field('Sotuv narxi, so‘m / dona','price',10000)}${field('Birlik tannarxi, so‘m','cost',6000)}${field('Oylik sotuv, dona','qty',1000)}${field('Doimiy xarajat, so‘m / oy','fixed',2000000)}${t==='Stress-test'?field('Sotuv hajmi kamayishi, %','drop',20)+field('Tannarx o‘sishi, %','rise',10):''}</div>${t==='Reja'?btn('Reja qoralamasini tayyorlash '+icon('arrow'),'type="submit"'):''}</form><div class="card"><div class="cardhead"><h2>${t==='Stress-test'?'Stress ssenariysi natijasi':'Hisob-kitob natijasi'}</h2></div><div id="businessResult"></div><div class="notice">Operatsion hisob. Soliq, kredit foizi va boshqa xarajatlar kiritilmagan. Miqdor oylik ko‘rsatkich sifatida olinadi.</div></div></div>`)}
function calcBusiness(){let f=$('#businessForm');if(!f)return;let v=n=>Number(f.elements[n]?.value||0),p=v('price'),c=v('cost'),q=v('qty'),fixed=v('fixed'),drop=v('drop'),rise=v('rise');let out=$('#businessResult');if(drop>100||drop<0){out.innerHTML='<div class="notice">Sotuv kamayishi 0–100% oralig‘ida bo‘lishi kerak.</div>';return}q*=1-drop/100;c*=1+rise/100;let rev=p*q,profit=rev-c*q-fixed,be=p>c?Math.ceil(fixed/(p-c)):null;out.innerHTML=`<div class="result"><span>Operatsion foyda / oy</span><strong class="${profit<0?'down':'up'}">${money(profit)} <span style="font-size:16px">so‘m</span></strong><div class="resultrow"><span>Tushum</span><b>${money(rev)} so‘m</b></div><div class="resultrow"><span>Jami xarajat</span><b>${money(c*q+fixed)} so‘m</b></div><div class="resultrow"><span>Operatsion marja</span><b>${rev?(profit/rev*100).toFixed(1)+'%':'Aniqlanmagan'}</b></div><div class="resultrow"><span>Zararsizlik hajmi</span><b>${be===null?'Erishib bo‘lmaydi':money(be)+' dona'}</b></div></div>`;return {revenue:rev,profit,breakeven:be}}
function generatePlan(){let f=$('#businessForm');if(!f.reportValidity())return;let r=calcBusiness();modal('Biznes reja qoralamasi',`<h3>${esc(f.elements.idea.value)}</h3><p>Oylik maqsad: ${money(Number(f.elements.qty.value))} dona savdo.</p><div class="result"><div class="resultrow"><span>Rejalashtirilgan tushum</span><b>${money(r.revenue)} so‘m</b></div><div class="resultrow"><span>Operatsion foyda</span><b>${money(r.profit)} so‘m</b></div></div><h3>Keyingi 3 qadam</h3><ol><li>Maqsadli mijozlar va talabni suhbatlar bilan tekshiring.</li><li>Ta’minotchi, logistika va doimiy xarajatlarni tasdiqlang.</li><li>Stress-testda sotuv kamayishini hisoblang.</li></ol><div class="notice">Bu kiritilgan raqamlardan tuzilgan shablon qoralama. Generativ AI yoki bozor tadqiqoti qo‘llanmagan.</div>`)}
function taxChecklist(){modal('Tekshirish ro‘yxati','<ol><li>Biznesning ro‘yxatdan o‘tgan shakli va faoliyatini aniqlang.</li><li>Tegishli davr uchun rasmiy manbani tekshiring.</li><li>Hisobot va hujjat muddatlarini qayd eting.</li><li>Murakkab holatni mutaxassis bilan tasdiqlang.</li></ol><p class="muted">Bu umumiy ish ro‘yxati, individual soliq xulosasi emas.</p>')}
function creditPage(){setTimeout(calcCredit,0);return `<div class="grid two-col"><form class="card" id="creditForm" oninput="calcCredit()" onsubmit="event.preventDefault()"><h2>Smart kredit kalkulyator</h2>${field('Kredit summasi, so‘m','principal',50000000)}<div class="formgrid">${field('Yillik nominal stavka, %','rate',24)}${field('Muddat, oy','months',24)}</div>${selectField('To‘lov usuli','method',['Annuitet','Differensial'])}${field('Bir martalik komissiya, so‘m','commission',0)}</form><div class="card"><h2>To‘lovlar bahosi</h2><div id="creditResult"></div><div class="notice">Bank taklifi emas. Foiz oylik nominal stavka (yillik / 12) bo‘yicha hisoblanadi. Sug‘urta va boshqa bank xarajatlari kiritilmagan.</div>${btn('Hujjatlar paketi','onclick="modal(\'Kreditga tayyorgarlik\',\'<ol><li>Biznes reja va pul oqimi prognozi.</li><li>Biznes ro‘yxati va moliyaviy hujjatlar.</li><li>Bank talab qilgan qo‘shimcha hujjatlar.</li></ol><p>Yakuniy ro‘yxatni tanlangan bank tasdiqlaydi.</p>\')"',true)}</div></div>`}
function calcCredit(){let f=$('#creditForm');if(!f)return;let p=+f.principal.value,i=+f.rate.value/1200,n=+f.months.value,fee=+f.commission.value;if(n<1||n>600||n%1){$('#creditResult').innerHTML='<p>1–600 oralig‘ida butun oy kiriting.</p>';return}let ann=i===0?p/n:p*i*Math.pow(1+i,n)/(Math.pow(1+i,n)-1),diff=f.elements.method.value==='Differensial',total=diff?p+p*i*(n+1)/2:ann*n;$('#creditResult').innerHTML=`<div class="result"><span>${diff?'Birinchi oy':'Oylik to‘lov'}</span><strong>${money(diff?p/n+p*i:ann)} so‘m</strong>${diff?`<div class="resultrow"><span>Oxirgi oy</span><b>${money(p/n+p/n*i)} so‘m</b></div>`:''}<div class="resultrow"><span>Jami foiz</span><b>${money(total-p)} so‘m</b></div><div class="resultrow"><span>Komissiya bilan jami</span><b>${money(total+fee)} so‘m</b></div></div>`}
function marketPage(){let t=tab||'Bozor pulsi';return header('Bozorni kuzating. Imkoniyatni ko‘ring.','Narxlar, mahsulotlar va hududlar — yagona ish maydonida.',btn(icon('plus')+' Mahsulot joylashtirish','onclick="addListing()"'))+tabs(['Bozor pulsi','O‘sish / pasayish','Narxlar jadvali','AI prognoz','Yangiliklar','Partiya xaridi','Arbitraj'])+(t==='AI prognoz'?forecastPage():t==='Yangiliklar'?`<div class="card"><span class="badge">Manbalar ulanmagan</span><h2>Biznesga ta’sir qiladigan yangiliklar</h2><p class="muted">Ishchi versiyada yangilikning asl manbasi, vaqti va AI xulosasi alohida ko‘rsatiladi. Hozir tasdiqlanmagan yangilik taqdim etilmaydi.</p>${link('Yangiliklar talablarini ko‘rish','spec',true)}</div>`:t==='Arbitraj'?arbitragePage():`<div class="filters"><input aria-label="Mahsulot qidirish" placeholder="Mahsulot nomini qidiring…" value="${esc(marketQuery)}" oninput="marketQuery=this.value;updateMarketRows()"><select aria-label="Viloyat" onchange="marketRegion=this.value;updateMarketRows()">${['Barcha hududlar','Toshkent','Samarqand','Xorazm'].map(r=>`<option ${r===marketRegion?'selected':''}>${r}</option>`).join('')}</select></div>${t==='Bozor pulsi'?`<section class="card" style="margin-bottom:20px"><div class="cardhead"><div><h2>Kartoshka / UZS</h2><div class="subtext">E’lon narxlari OHLC namunasi · Qo‘yliq</div></div><span class="badge">Sintetik grafik</span></div>${chart(true)}</section>`:''}<section class="card"><div class="cardhead"><h2>${t==='Partiya xaridi'?'Ulgurji takliflar':t==='O‘sish / pasayish'?'Narx o‘zgarishi bo‘yicha':'Hududlar bo‘yicha mahsulotlar'}</h2><span class="subtext">Namuna narxlar · so‘m/kg</span></div><div id="marketRows">${productTable(filteredProducts(t))}</div></section>${t==='Partiya xaridi'?'<div class="notice">Mahsulot kartasini ochib, kerakli miqdor bo‘yicha demo xarid so‘rovini yuboring. Haqiqiy rezerv yaratilmaydi.</div>':''}`)}
function filteredProducts(t=tab){let list=products.filter(p=>p.name.toLowerCase().includes(marketQuery.toLowerCase())&&(marketRegion==='Barcha hududlar'||p.region===marketRegion));return t==='O‘sish / pasayish'?[...list].sort((a,b)=>b.change-a.change):list}
function updateMarketRows(){if($('#marketRows'))$('#marketRows').innerHTML=productTable(filteredProducts())}
function productDetail(id){let p=products.find(p=>p.id===id);modal(esc(p.name),`<span class="badge">Demo e’lon · ${esc(p.kind)}</span><h2>${money(p.price)} <small class="muted">so‘m / kg</small></h2><div class="resultrow"><span>Hudud va bozor</span><b>${p.region} · ${esc(p.market)}</b></div><div class="resultrow"><span>Mavjud miqdor</span><b>${money(p.stock)} kg</b></div><div class="resultrow"><span>Minimal xarid</span><b>100 kg</b></div><div class="resultrow"><span>Yetkazib berish</span><b>Alohida kelishiladi</b></div><p class="muted">Sifat va nav ma’lumotlari namuna. Sotuvchi tasdiqlanmagan.</p><form onsubmit="event.preventDefault();purchase(${p.id},this)">${field('Xarid miqdori, kg','buyQty',100)}<div id="purchaseError" class="down"></div>${btn('Demo xarid so‘rovi','type="submit"')}</form>`)}
function purchase(id,f){let p=products.find(x=>x.id===id),q=+f.buyQty.value;if(q<100||q>p.stock){$('#purchaseError').textContent=`100–${p.stock} kg oralig‘ida kiriting.`;return}modal('Xarid so‘rovi tayyor',`<p>${esc(p.name)} · ${money(q)} kg</p><div class="result"><span>Mahsulot qiymati</span><strong>${money(q*p.price)} so‘m</strong></div><div class="notice">Demo so‘rov. Sotuvchiga yuborilmadi, pul yechilmadi va mahsulot rezerv qilinmadi.</div>${btn('Ekspeditor tanlash →','onclick="document.querySelector(\'#modal\').close();navigate(\'logistics\')"')}`)}
function addListing(){modal('Mahsulot joylashtirish',`<form onsubmit="event.preventDefault();saveListing(this)">${field('Mahsulot nomi','name','','text')}<div class="formgrid">${field('Narx, so‘m/kg','price','')}${field('Miqdor, kg','stock','')}${selectField('Viloyat','region',['Toshkent','Samarqand','Xorazm'])}${field('Bozor nomi','market','','text')}</div><div class="notice">E’lon faqat ushbu demo sessiyada qo‘shiladi.</div>${btn('E’lonni qo‘shish','type="submit"')}</form>`)}
function saveListing(f){if(+f.price.value<=0||+f.stock.value<=0){notify('Narx va miqdor noldan katta bo‘lsin.');return}products.push({id:Date.now(),name:f.elements.name.value,code:f.elements.name.value.slice(0,2).toUpperCase(),kind:'Yangi e’lon',price:+f.price.value,stock:+f.stock.value,region:f.region.value,market:f.market.value,unit:'kg',change:0});$('#modal').close();notify('E’lon demo sessiyasiga qo‘shildi');render()}
function forecastPage(){return `<div class="card"><div class="cardhead"><div><h2>Kartoshka: prognoz ko‘rinishi</h2><div class="subtext">Haqiqiy bashorat emas — interfeys namunasi</div></div><select aria-label="Prognoz muddati" onchange="forecastResult(this.value)">${[7,14,30,60,90].map(x=>`<option value="${x}">${x} kun</option>`).join('')}</select></div><div id="forecastResult">${forecastResultHTML(7)}</div><div class="notice">Ishchi versiyada model sanasi, ishonch oralig‘i, manba va tarixiy xato ko‘rsatiladi. Sintetik raqamlar xarid yoki sotuv qarori uchun mo‘ljallanmagan.</div></div>`}
function forecastResultHTML(days){let mid=Math.round(3800*(1+days*.001)),range=days*12;return `<div class="grid two-col"><div class="result"><span>${days} kundan keyingi namuna baho</span><strong>${money(mid)} so‘m/kg</strong><p>Namuna oralig‘i: ${money(mid-range)}–${money(mid+range)} so‘m</p></div><div><h3>Prognoz pasporti</h3><div class="resultrow"><span>Model</span><b>Ulanmagan</b></div><div class="resultrow"><span>Tarixiy aniqlik</span><b>O‘lchanmagan</b></div><div class="resultrow"><span>Holat</span><b>Dizayn namunasi</b></div></div></div>`}
function forecastResult(days){$('#forecastResult').innerHTML=forecastResultHTML(+days)}
function arbitragePage(){setTimeout(calcArbitrage,0);return `<div class="grid two-col"><form class="card" id="arbForm" oninput="calcArbitrage()" onsubmit="event.preventDefault()"><h2>Hududlararo narx farqi</h2><div class="formgrid">${field('Xarid narxi, so‘m/kg','buy',3200)}${field('Sotuv narxi, so‘m/kg','sell',3800)}${field('Miqdor, kg','amount',2000)}${field('Transport, so‘m','transport',600000)}${field('Boshqa xarajat, so‘m','other',150000)}${field('Yo‘qotish, %','loss',2)}</div></form><div class="card"><h2>Imkoniyat bahosi</h2><div id="arbResult"></div><p class="muted">Soliq va komissiya kiritilgan bo‘lsa “Boshqa xarajat”ga qo‘shing. Bu kiritilgan farazlar bo‘yicha hisob.</p></div></div>`}
function calcArbitrage(){let f=$('#arbForm');if(!f)return;let loss=+f.loss.value;if(loss>100){$('#arbResult').textContent='Yo‘qotish 0–100% oralig‘ida bo‘lsin.';return}let revenue=+f.sell.value*+f.amount.value*(1-loss/100),cost=+f.buy.value*+f.amount.value+ +f.transport.value+ +f.other.value;$('#arbResult').innerHTML=`<div class="result"><span>Hisobiy natija</span><strong class="${revenue-cost<0?'down':'up'}">${money(revenue-cost)} so‘m</strong><div class="resultrow"><span>Sotuv tushumi</span><b>${money(revenue)}</b></div><div class="resultrow"><span>Jami xarajat</span><b>${money(cost)}</b></div></div>`}
function startChat(q){chatMessages.push({role:'user',text:q},{role:'assistant',text:demoReply(q)});navigate('adviser');if(page==='adviser')render()}
function demoReply(q){if(/foyda|xarajat|kirim|chiqim|pul/i.test(q))return 'Namuna javob: foydani hisoblash uchun tushumdan tannarx va tegishli xarajatlarni ayiring. Pul oqimini alohida kuzating: kredit tushumi foyda emas.\n\nBiznes reja → Kalkulyator bo‘limida narx, tannarx, miqdor va doimiy xarajatlarni kiriting. Bu oldindan yozilgan demo javob, AI tahlili emas.';if(/reja|biznes|g‘oya/i.test(q))return 'Namuna javob: rejangizni uch savoldan boshlang: kimga sotasiz, qanday muammoni hal qilasiz va bir birlikdan qancha hissa foyda olasiz?\n\nBiznes reja sahifasida hisob parametrlarini kiritib, keyin stress-testni sinang. Bu oldindan yozilgan demo javob.';return 'Bu chat dizayn namunasi. Sizning xabaringiz demo sessiyada ko‘rinadi, lekin AI provayderiga yuborilmaydi. Ishchi versiya manbali javob, suhbat tarixi va ovozli muloqot bilan ulanadi. Hozir biznes reja, kalkulyator va daftar oqimlarini sinashingiz mumkin.'}
function adviser(){return header(role==='business'?'Sizning AI biznes hamrohingiz.':'Safaringizni birga rejalashtiramiz.','Matnli va ovozli maslahat uchun yagona suhbat maydoni.')+`<div class="chat"><div class="chatintro"><div class="ai-logo" style="color:var(--green);display:flex;justify-content:center">${icon('spark')}</div><h2>Bugun nimani hal qilamiz?</h2><p class="muted">G‘oya, hisob-kitob yoki keyingi qadam.</p><div class="pillrow" style="justify-content:center">${['Biznes reja tuzish','Foydani hisoblash','Xarajatlarni tahlil qilish'].map(x=>`<button class="chip" onclick="startChat('${x}')">${x}</button>`).join('')}</div></div><div class="notice">Demo suhbat: javoblar shablon asosida. Generativ AI va ovozli xizmat hali ulanmagan.</div><div class="chatmsgs">${chatMessages.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}</div><form class="chatbox" onsubmit="event.preventDefault();sendChat(this)"><textarea name="message" aria-label="AI uchun xabar" placeholder="Savolingizni yozing…" required></textarea><button class="icon-button" type="button" aria-label="Ovozli suhbat haqida" onclick="voiceInfo()">${icon('mic')}</button>${btn(icon('arrow'),'type="submit" aria-label="Xabar yuborish"')}</form></div>`}
function sendChat(f){let q=f.message.value.trim();if(!q)return;chatMessages.push({role:'user',text:q},{role:'assistant',text:demoReply(q)});render();$('.chatbox').scrollIntoView({block:'nearest'})}
function voiceInfo(){modal('Ovozli muloqot',`<p>Ovozli xizmat integratsiyasi hali ulanmagan.</p><ol><li>Mikrofonga rozilik.</li><li>Yozish va matnga o‘girish.</li><li>Transkriptni tekshirish.</li><li>Javob yoki daftar qoralamasini tasdiqlash.</li></ol><div class="notice">Hozir ma’lumotni matn orqali kiriting. Ovoz yozib olinmaydi.</div>`)}
const drivers=[['Javohir Rasulov','JR','Isuzu NPR · 5 tonna','Toshkent','Toshkent → Samarqand','Kelishiladi'],['Sardor Aliyev','SA','Gazelle · 1,5 tonna','Samarqand','Samarqand → Buxoro','Kelishiladi'],['Otabek Rahimov','OR','MAN · 20 tonna','Xorazm','Urganch → Toshkent','Kelishiladi']];
function logisticsPage(){return header(role==='business'?'Yukingizga mos hamroh toping.':'Xizmatlaringizni bozorga olib chiqing.','Hudud va transport sig‘imi bo‘yicha ekspeditorlar.',role==='forwarder'?btn(icon('plus')+' Xizmat joylashtirish','onclick="publishDriver()"'):'')+`<div class="filters"><select aria-label="Ekspeditor viloyati" onchange="filterDrivers(this.value)"><option>Barcha hududlar</option><option>Toshkent</option><option>Samarqand</option><option>Xorazm</option></select></div><div class="grid courses" id="driverCards">${driverCards('Barcha hududlar')}</div><div class="notice">Ekspeditorlar — sintetik profil namunalari. Demo buyurtmalar hech kimga yuborilmaydi.</div>`}
function driverCards(region){return drivers.map((d,i)=>region!=='Barcha hududlar'&&d[3]!==region?'':`<div class="card"><div class="driver"><div class="avatar">${d[1]}</div><div><h3>${d[0]}</h3><p>${d[3]} · Demo profil</p></div></div><div class="driver-info"><span>Avtomobil</span><b>${d[2]}</b></div><div class="driver-info"><span>Yo‘nalish</span><b>${d[4]}</b></div><div class="driver-info"><span>Tarif</span><b>${d[5]}</b></div><div style="margin-top:20px">${btn('Buyurtma so‘rovi '+icon('arrow'),`onclick="requestShipment(${i})"`)}</div></div>`).join('')}
function filterDrivers(r){$('#driverCards').innerHTML=driverCards(r)}
function requestShipment(i){modal('Tashish buyurtmasi',`<p class="muted">Ekspeditor: ${drivers[i][0]}</p><form onsubmit="event.preventDefault();createShipment(this)">${field('Yo‘nalish','route',drivers[i][4],'text')}${field('Yuk nomi','cargo','Kartoshka','text')}<div class="formgrid">${field('Og‘irlik, kg','weight',1000)}${field('Taklif qilinayotgan haq, so‘m','price',1000000)}</div><div class="notice">Bu demo so‘rov: haqiqiy ekspeditorga yuborilmaydi.</div>${btn('Demo buyurtma yaratish','type="submit"')}</form>`)}
function createShipment(f){if(+f.weight.value<=0||+f.price.value<=0){notify('Miqdor va haq noldan katta bo‘lsin.');return}orders.unshift({id:'BP-D'+(orders.length+1),route:f.route.value,cargo:f.cargo.value+' · '+f.weight.value+' kg',price:+f.price.value,status:'Yangi so‘rov'});$('#modal').close();notify('Demo buyurtma qo‘shildi. Ekspeditor kabinetida ko‘rishingiz mumkin.');render()}
function publishDriver(){modal('Xizmat e’loni',`<form onsubmit="event.preventDefault();document.querySelector('#modal').close();notify('Demo xizmat e’loni tayyorlandi. Haqiqiy bozorda chop etilmadi.')">${field('Yo‘nalish','route','Toshkent → Samarqand','text')}${field('Bo‘sh vaqt','date','2026-09-20','date')}${field('Tarif izohi','rate','Kelishiladi','text')}${btn('Demo e’lonni tayyorlash','type="submit"')}</form>`)}
function orderRows(list){return list.map(o=>`<div class="order"><div><span class="subtext">${o.id}</span><h3>${esc(o.route)}</h3><p>${esc(o.cargo)}</p><span class="badge ${o.status==='Yangi so‘rov'?'orange':''}">${o.status}</span></div><div><b>${money(o.price)} so‘m</b><div style="margin-top:12px">${btn('Tafsilotlar',`onclick="orderDetail('${o.id}')"`,true)}</div></div></div>`).join('')||'<div class="empty">Bu bo‘limda buyurtma yo‘q.</div>'}
function ordersPage(history){return header(history?'Har bir safar — hisobda.':'Buyurtmalarni boshqaring.','Buyurtma holati va kelishilgan shartlarni kuzating.')+`<div class="card">${orderRows(orders.filter(o=>history?['Yopildi','Bekor qilindi'].includes(o.status):!['Yopildi','Bekor qilindi'].includes(o.status)))}</div>`}
function orderDetail(id){let o=orders.find(x=>x.id===id),states=['Yangi so‘rov','Taklif yuborildi','Tasdiqlandi','Yuk qabul qilindi','Yo‘lda','Yetkazildi','Qabul tasdiqlandi','Yopildi'],next=states[states.indexOf(o.status)+1];modal(o.id,`<h3>${esc(o.route)}</h3><p>${esc(o.cargo)}</p><div class="resultrow"><span>Kelishuv summasi</span><b>${money(o.price)} so‘m</b></div><div class="resultrow"><span>Holat</span><b>${o.status}</b></div><div class="notice">Demo oqimda har bosqichni sinash mumkin. Ishchi tizimda tasdiqlar tegishli tomon tomonidan beriladi.</div>${next?btn(next+' →',`onclick="advanceOrder('${id}','${next}')"`):'<span class="badge">Buyurtma yakunlangan</span>'}`)}
function advanceOrder(id,next){let o=orders.find(x=>x.id===id);o.status=next;$('#modal').close();render();notify('Demo holat: '+next)}
function calculatorPage(){return header('Har bir kilometrni hisoblang.','Avtomobil, yoqilg‘i va safar xarajatlaridan aniqroq tarifga.')+`<div class="grid two-col"><form class="card" id="tripForm" oninput="calcTrip()" onsubmit="event.preventDefault()"><div class="cardhead"><h2>Safar parametrlari</h2><span class="badge">Isuzu NPR</span></div><div class="field"><label for="orderCode">Buyurtma</label><select id="orderCode" onchange="loadTripOrder(this.value)"><option value="">Qo‘lda hisoblash</option>${orders.map(o=>`<option value="${o.id}">${o.id} · ${esc(o.route)}</option>`).join('')}</select></div><div class="formgrid">${field('Yukli masofa, km','loaded',250)}${field('Bo‘sh qaytish, km','empty',250)}${field('Yukli sarf, l/100km','loadedFuel',14)}${field('Bo‘sh sarf, l/100km','emptyFuel',11)}${field('Yoqilg‘i, so‘m/l','fuel',12000)}${field('Boshqa xarajat, so‘m','other',250000)}${field('Amortizatsiya, so‘m/km','wear',300)}${field('Buyurtma haqi, so‘m','fee',1500000)}</div></form><div class="card"><h2>Safar iqtisodiyoti</h2><div id="tripResult"></div><div class="notice">Soliq va komissiyalarni zarur bo‘lsa boshqa xarajatlarga kiriting. Masofa qo‘lda kiritilgan; xarita ulanmagan.</div>${btn('Hisobni daftarga tayyorlash','onclick="tripToNote()"',true)}</div></div>`}
function loadTripOrder(id){let o=orders.find(x=>x.id===id);if(o){$('#tripForm').fee.value=o.price;calcTrip()}}
function calcTrip(){let f=$('#tripForm');if(!f)return;let v=k=>+f.elements[k].value,liters=(v('loaded')*v('loadedFuel')+v('empty')*v('emptyFuel'))/100,fuel=liters*v('fuel'),wear=(v('loaded')+v('empty'))*v('wear'),total=fuel+wear+v('other'),profit=v('fee')-total;$('#tripResult').innerHTML=`<div class="result"><span>Safar bo‘yicha hisobiy natija</span><strong class="${profit<0?'down':'up'}">${money(profit)} so‘m</strong><div class="resultrow"><span>Yoqilg‘i (${liters.toFixed(1)} l)</span><b>${money(fuel)}</b></div><div class="resultrow"><span>Amortizatsiya</span><b>${money(wear)}</b></div><div class="resultrow"><span>Jami xarajat</span><b>${money(total)}</b></div><div class="resultrow"><span>Kelishilgan haq</span><b>${money(v('fee'))}</b></div></div>`;return {total,fee:v('fee')}}
function tripToNote(){let r=calcTrip();modal('Safar hisobi qoralamasi',`<p>Kirim: <b>${money(r.fee)} so‘m</b></p><p>Xarajat: <b>${money(r.total)} so‘m</b></p><div class="notice">Bu rejalashtirilgan hisob. Haqiqiy pul harakati bo‘lganda daftar qaydini kiriting; kalkulyator avtomatik yozuv yaratmaydi.</div>${btn('Qo‘lda qayd kiritish','onclick="addNote()"')}`)}
function notebookPage(){let inc=notes.filter(n=>n.type==='in').reduce((s,n)=>s+n.amount,0),out=notes.filter(n=>n.type==='out').reduce((s,n)=>s+n.amount,0);return header(role==='business'?'B.P.Ai-daftar':'AI Ekspeditor-daftar','Biznesingizning har bir kirimi va chiqimi nazoratda.',btn(icon('plus')+' Qayd qo‘shish','onclick="addNote()"'))+`<div class="grid kpis" style="grid-template-columns:repeat(3,minmax(0,1fr))">${kpi('Kirim',money(inc),'so‘m','Saqlangan qaydlar','down')}${kpi('Chiqim',money(out),'so‘m','Saqlangan qaydlar','up',false)}${kpi('Sof pul oqimi',money(inc-out),'so‘m','Foyda hisoboti emas','wallet')}</div><div class="card"><div class="cardhead"><h2>Operatsiyalar</h2><div class="actions"><select aria-label="Operatsiya turi" onchange="filterNotes(this.value)"><option value="all">Barchasi</option><option value="in">Kirim</option><option value="out">Chiqim</option></select>${btn('CSV yuklash','onclick="exportNotes()"',true)}</div></div><div id="noteRows">${noteTable(notes)}</div></div><div class="notice">Qaydlar serverda saqlanadi va faqat sizning akkauntingizga tegishli. Ovozli qayd hali ulanmagan.</div>`}
function noteTable(list){return `<div class="tablewrap"><table><thead><tr><th>Operatsiya</th><th>Kategoriya</th><th>Sana</th><th>Summa</th></tr></thead><tbody>${list.map(n=>`<tr><td><b>${esc(n.name)}</b></td><td>${esc(n.category)}</td><td>${n.date}</td><td class="${n.type==='in'?'up':'down'}"><b>${n.type==='in'?'+':'−'}${money(n.amount)} so‘m</b></td></tr>`).join('')||'<tr><td colspan="4" class="empty">Hali qayd yo‘q.</td></tr>'}</tbody></table></div>`}
function filterNotes(type){$('#noteRows').innerHTML=noteTable(notes.filter(n=>type==='all'||n.type===type))}
function addNote(){if(!BP.isAuthed()){notify('Qayd uchun tizimga kiring');navigate('login');return}const today=new Date().toISOString().slice(0,10);modal('Yangi hisob qaydi',`<form onsubmit="event.preventDefault();saveNote(this)">${field('Izoh','noteName','','text')}<div class="formgrid">${selectField('Operatsiya turi','type',['Kirim','Chiqim'])}${field('Summa, so‘m','amount','')}${field('Sana','date',today,'date')}${selectField('Kategoriya','category',['Savdo','Xarid','Logistika','Ijara','Boshqa'])}</div><div class="notice">Saqlashdan oldin summa va turini tekshiring. Ovozli qayd keyingi bosqichda.</div><div class="actions">${btn('Qaydni saqlash','type="submit"')}${btn(icon('mic')+' Ovoz','type="button" onclick="voiceInfo()"',true)}</div></form>`)}
async function saveNote(f){if(+f.amount.value<=0){notify('Summa noldan katta bo‘lishi kerak.');return}try{const entry=await BP.api('/api/v1/notebook/entries/',{method:'POST',body:JSON.stringify({name:f.noteName.value,type:f.type.value==='Kirim'?'in':'out',amount:+f.amount.value,date:f.date.value,category:f.category.value})});notes.unshift(entry);$('#modal').close();render();notify('Qayd saqlandi')}catch(e){notify(e.message||'Saqlanmadi')}}
function exportNotes(){const safe=x=>'"'+String(x).replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';let csv='\ufeffIzoh,Tur,Summa,Sana,Kategoriya\n'+notes.map(n=>[n.name,n.type==='in'?'Kirim':'Chiqim',n.amount,n.date,n.category].map(safe).join(',')).join('\n');download('Bozor-Puls-daftar.csv',csv,'text/csv;charset=utf-8')}
function download(name,text,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function profilePage(){const initials=esc((profile.name||'BP').split(' ').map(x=>x[0]).join('').slice(0,2));return header('Profilingiz — ishonchning boshlanishi.','Shaxsiy va faoliyatingizga oid ma’lumotlar.')+`<form class="card" onsubmit="event.preventDefault();saveProfile(this)"><div class="cardhead"><div class="driver"><div class="avatar">${initials}</div><div><h3>${esc(profile.name)}</h3><p>${esc(profile.email||'')} · ${role==='business'?'Tadbirkor':'Ekspeditor'}</p></div></div></div><div class="formgrid">${field('F.I.Sh.','fullName',profile.name,'text')}${role==='business'?field('Biznes nomi','business',profile.business,'text'):''}<div class="field"><label for="phone">Telefon</label><input id="phone" name="phone" type="tel" value="${esc(profile.phone||'')}"></div>${selectField('Viloyat','region',['Toshkent','Samarqand','Xorazm','Andijon','Buxoro'])}${role==='forwarder'?field('Avtomobil','vehicle',profile.vehicle||'','text')+field('Yuk sig‘imi','capacity',profile.capacity||'','text'):field('Faoliyat turi','activity',profile.activity||'','text')+field('Bozor','market',profile.market||'','text')}</div><div class="notice">Ma’lumotlar serverda saqlanadi va boshqa foydalanuvchilarga ko‘rinmaydi.</div>${btn('O‘zgarishlarni saqlash','type="submit"')}</form>`}
async function saveProfile(f){if(!BP.isAuthed()){notify('Avval tizimga kiring');return}try{const body={full_name:f.fullName.value,phone:f.phone.value};if(role==='business'){body.business={business_name:f.business.value,region:f.region.value,activity:f.activity?.value||'',market:f.market?.value||''}}else{body.forwarder={vehicle:f.vehicle?.value||'',capacity:f.capacity?.value||'',region:f.region.value}}const me=await BP.api('/api/v1/me/',{method:'PATCH',body:JSON.stringify(body)});BP.setSession({user:me,access:BP.getAccess(),refresh:localStorage.getItem('bp_refresh')});applyUser(me);render();notify('Profil saqlandi')}catch(e){notify(e.message||'Saqlanmadi')}}
function walletPage(){return header('Mablag‘laringiz — bir ko‘rinishda.','Hisob, operatsiyalar va kartalar uchun ish maydoni.')+`<div class="grid two-col"><div class="wallet"><small>KARMON · ULANMAGAN</small><strong>— <span style="font-size:17px">so‘m</span></strong><span>To‘lov provayderi yo‘q</span><div class="wallet-footer"><span>Hisob ulanmagan</span><span>UZS</span></div></div><div class="card"><h2>Pul operatsiyalari</h2><div class="actions" style="flex-wrap:wrap">${btn(icon('arrow')+' O‘tkazma','onclick="paymentInfo()"')}${btn(icon('down')+' Pul yechish','onclick="paymentInfo()"',true)}${btn(icon('plus')+' Karta ulash','onclick="paymentInfo()"',true)}</div><div class="notice">To‘lov provayderi ulanmagan. Balans ko‘rsatilmaydi va pul amallari ochilmagan.</div></div></div><div class="card below"><div class="cardhead"><h2>Hisob tarixi</h2><span class="badge">Ulanmagan</span></div><p class="muted" style="padding:12px 0">Operatsiyalar to‘lov hamkori ulanganidan keyin paydo bo‘ladi.</p></div>`}
function paymentInfo(){modal('To‘lov integratsiyasi kerak',`<p>Haqiqiy operatsiyalar vakolatli to‘lov hamkori ulanganidan keyin ishlaydi.</p><div class="notice">Hozir pul o‘tkazilmaydi, karta ulanmaydi va mablag‘ yechilmaydi.</div><p>Ishchi oqim: rekvizit → summa va komissiya → tasdiqlash → provayder natijasi → hisob tarixi.</p>${link('Karmon talablarini ko‘rish','spec',true)}`);$('#modal').querySelector('a').onclick=()=>$('#modal').close()}
function settingsPage(){return header('Ish maydonini o‘zingizga moslang.','Qulaylik, bildirishnoma va maxfiylik.')+`<form class="card" onsubmit="event.preventDefault();notify('Sozlamalar mahalliy saqlandi (bildirishnomalar yuborilmaydi)')"><div class="formgrid">${selectField('Til','language',['O‘zbekcha (lotin)'])}${selectField('Vaqt zonasi','timezone',['Asia/Tashkent (UTC+5)'])}</div>${[['Buyurtma bildirishnomalari','Buyurtma holati o‘zgarganda xabar.'],['Learning eslatmalari','O‘rganishni davom ettirish uchun eslatma.'],['AI kontekstiga ruxsat','Ishchi versiyada daftar va reja ma’lumotidan foydalanish.']].map((s,i)=>`<div class="settingsrow"><div><h3>${s[0]}</h3><p>${s[1]}</p></div><input type="checkbox" aria-label="${s[0]}" ${i===0?'checked':''}></div>`).join('')}<div class="notice">Haqiqiy push/email xabarlari hali ulanmagan. AI kontekst ruxsati Stage 3 da ishlaydi.</div>${btn('Saqlash','type="submit"')} ${BP.isAuthed()?btn('Chiqish','type="button" onclick="logout()"',true):`<a class="btn secondary" href="#login">Kirish</a>`}</form>`}
function helpPage(){return header('Yordam berishga tayyormiz.','Savollaringiz va takliflaringiz uchun yagona markaz.')+tabs(['Yordam','Obuna'])+((tab||'Yordam')==='Obuna'?`<div class="grid courses">${[['Free','Boshlash uchun','Learning va asosiy hisob vositalari.'],['Business','Tadbirkor uchun','Reja, tahlil, AI va kengaytirilgan daftar.'],['Logistics','Ekspeditor uchun','Buyurtmalar va safar tahlili.']].map((x,i)=>`<div class="card"><span class="badge">${x[1]}</span><h2>${x[0]}</h2><h3>Narx tasdiqlanmagan</h3><p class="muted">${x[2]}</p>${btn('Tarif haqida',`onclick="notify('Tarif narxi, limitlari va to‘lov shartlari hali tasdiqlanmagan.')"`,i!==1)}</div>`).join('')}</div>`:`<div class="grid two-col"><div class="card"><h2>Ko‘p beriladigan savollar</h2>${[['Bu haqiqiy platformami?','Stage 1: haqiqiy login, profil va daftar ishlaydi. AI, jonli narx va to‘lov hali ulanmagan.'],['Ma’lumotlar saqlanadimi?','Ha — profil va kirim-chiqim server bazasida. Boshqa foydalanuvchi ko‘ra olmaydi.'],['Narxlar jonlimi?','Yo‘q. Grafik va narxlar sintetik namunalar; real manba keyingi bosqichda.']].map(x=>`<details class="settingsrow" style="display:block"><summary>${x[0]}</summary><p style="margin-top:12px">${x[1]}</p></details>`).join('')}</div><form class="card" onsubmit="event.preventDefault();supportDraft(this)"><h2>Murojaat qoralamasi</h2>${field('Mavzu','subject','','text')}<div class="field"><label for="helptext">Xabaringiz</label><textarea id="helptext" name="text" required></textarea></div><div class="notice">Ofis manzili va aloqa kanallari berilmagan. Ushbu qoralama operatorga yuborilmaydi.</div>${btn('Qoralamani ko‘rish','type="submit"')}</form></div>`)}
function supportDraft(f){modal('Murojaat qoralamasi',`<h3>${esc(f.subject.value)}</h3><p style="white-space:pre-wrap">${esc(f.text.value)}</p><div class="notice">Yuborilmadi. Haqiqiy yordam kanali ishchi platformada ulanadi.</div>`)}
function authPage(register){return `<div class="card auth"><div class="auth-art"><img src="favicon.svg" width="50" alt="Bozor-Puls"><h2>Biznesingiz.<br>Bilimingiz.<br>Yangi imkoniyatingiz.</h2><p>Tadbirkor va ekspeditorlar uchun yagona ish maydoni.</p></div><form class="auth-form" onsubmit="event.preventDefault();${register?'prepareRegister(this)':'doLogin(this)'}"><div class="eyebrow">BOZOR-PULS.AI</div><h2>${register?'Profil yarating':'Xush kelibsiz'}</h2>${register?field('F.I.Sh.','name','','text'):''}${field('Email','email','','email')}${field('Parol','password','','password')}${register?'<div class="field"><label for="phone">Telefon (ixtiyoriy)</label><input id="phone" name="phone" type="tel" value=""></div>':''}<div class="notice">Email + parol orqali haqiqiy hisob. SMS OTP keyingi bosqichda.</div>${register?'<label style="font-size:13px;display:block;margin-bottom:20px"><input type="checkbox" name="consent" required> Ommaviy oferta va maxfiylikka roziman</label>':''}${btn(register?'Rolni tanlash →':'Kirish →','type="submit"')}<p style="font-size:14px;margin-top:25px"><a href="#${register?'login':'register'}" class="inline-link">${register?'Profilingiz bormi? Kirish':'Yangi profil yaratish'}</a></p></form></div>`}
function prepareRegister(f){pendingRegister={full_name:f.name.value.trim(),email:f.email.value.trim().toLowerCase(),password:f.password.value,phone:(f.phone?.value||'').trim(),consent:true};navigate('role')}
async function doLogin(f){try{const data=await BP.api('/api/v1/auth/login/',{method:'POST',body:JSON.stringify({email:f.email.value.trim().toLowerCase(),password:f.password.value})});BP.setSession(data);applyUser(data.user);await loadNotes();notify('Xush kelibsiz');navigate('overview')}catch(e){notify(e.message||'Kirib bo‘lmadi')}}
function rolePage(){if(!pendingRegister){return header('Avval akkaunt oching.','Rol tanlash uchun ro‘yxatdan o‘ting.')+`<div class="card">${link('Ro‘yxatdan o‘tish','register')}${link('Kirish','login',true)}</div>`}return header('Siz uchun qaysi ish maydoni?','Asosiy faoliyatingizga mos kabinetni tanlang. Rol keyin o‘zgarmaydi.')+`<div class="role-grid"><button class="role-option" onclick="finishRegister('business')">${icon('bag')}<h3>Tadbirkor</h3><p>Biznes reja, bozor tahlili, mahsulot savdosi va hisob-kitob.</p><span class="inline-link">Tadbirkor kabineti →</span></button><button class="role-option" onclick="finishRegister('forwarder')">${icon('truck')}<h3>Ekspeditor</h3><p>Buyurtmalar, avtomobil, yo‘nalishlar va safar iqtisodiyoti.</p><span class="inline-link">Ekspeditor kabineti →</span></button></div>`}
async function finishRegister(selectedRole){if(!pendingRegister){navigate('register');return}try{const data=await BP.api('/api/v1/auth/register/',{method:'POST',body:JSON.stringify({...pendingRegister,role:selectedRole})});pendingRegister=null;BP.setSession(data);applyUser(data.user);notes=[];notify('Hisob yaratildi');navigate('overview')}catch(e){notify(e.message||'Ro‘yxatdan o‘tib bo‘lmadi')}}
function showNotifications(){modal('Bildirishnomalar',`<div class="notice">Push bildirishnomalar hali ulanmagan. Buyurtma holatlari Stage 2 da serverdan keladi.</div>`)}
function specPage(){return header('G‘oyadan ishlaydigan mahsulotgacha.','To‘liq texnik topshiriq · UI/UX konsepsiyasi · Versiya 1.0',`<a class="btn" href="Bozor-Puls-Ai-TZ.md" download>${icon('file')} TZ yuklab olish</a>`)+`<article class="card doc" id="specContent"><p>Texnik topshiriq yuklanmoqda…</p></article>`}
async function loadSpec(){try{let r=await fetch('Bozor-Puls-Ai-TZ.md');if(!r.ok)throw Error();let t=await r.text();let lines=t.split('\n'),html='',table=false,list=false;for(let line of lines){if(line.startsWith('|')){if(/^\|[\s|:-]+\|$/.test(line))continue;if(!table){html+='<div class="tablewrap"><table>';table=true}html+='<tr>'+line.slice(1,-1).split('|').map(c=>`<td>${esc(c.trim())}</td>`).join('')+'</tr>';continue}if(table){html+='</table></div>';table=false}if(/^#{1,3} /.test(line)){let n=line.match(/^#+/)[0].length;html+=`<h${n}>${esc(line.slice(n+1))}</h${n}>`}else if(line.trim()){html+=`<p>${esc(line).replace(/\*\*(.*?)\*\*/g,'<b>$1</b>')}</p>`}}if(table)html+='</table></div>';if($('#specContent'))$('#specContent').innerHTML=html}catch(e){if($('#specContent'))$('#specContent').innerHTML='<p>Hujjatni ochishda xato. Yuqoridagi yuklash havolasidan foydalaning.</p>'}}
window.addEventListener('hashchange',()=>{tab='';guardAndRender();window.scrollTo(0,0)});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
bootSession();
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'navigate_bozor_puls_demo',description:'Open a page of the Bozor-Puls design prototype. Does not perform real transactions.',inputSchema:{type:'object',properties:{page:{type:'string',enum:Object.keys(titles)}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Object.hasOwn(titles,input.page))throw new Error('Unknown page');page=input.page;history.replaceState(null,'','#'+page);tab='';render();return {page,title:titles[page],mode:'design_demo'}}},{signal:life.signal})).catch(()=>{});window.addEventListener('pagehide',()=>life.abort(),{once:true})}catch(e){}}
